// #d9aa30282ea83831ce4afdeb — кандидат на версии без сценария: business видит в списке причину «אין תרחיש לגרסה»,
// гость видит «הסימולציה עדיין לא מוכנה» и путь к команде. Кейс CAND-004.
// НЕ prod-safe: создаёт кандидата «QA-AUTO-NS-…» (link_only — без письма/SMS); не удаляется (правило проекта).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink, candidateRow, SIMULATION } from '../candidate-call/support';

test.describe.configure({ mode: 'serial' });

const NO_SCENARIO_SIMULATION = process.env.QA_NO_SCENARIO_SIMULATION || 'QA-DS r2 טיוטה וגרסאות';
const MARKER = 'אין תרחיש לגרסה';
const TOOLTIP = 'המועמד/ת לא יכול/ה להתחיל את הסימולציה כי לגרסה שלה אין תרחיש. כדאי לשייך גרסה עם תרחיש או להשלים את התרחיש.';

let name = '';
let link = '';

test.describe('Кандидаты — версия без сценария (#d9aa30282ea83831ce4afdeb)', () => {
  test('business: кандидат на версии без сценария — «קישור נוצר» + «אין תרחיש לגרסה» с подсказкой; у версии со сценарием метки нет @desktop @data #d9aa30282ea83831ce4afdeb', async ({ asUser }) => {
    test.setTimeout(120_000);
    const business = await asUser('business');
    name = `QA-AUTO-NS-${runStamp()}`;
    link = await createCandidateLink(business, name, NO_SCENARIO_SIMULATION);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}», не удаляется` });

    // Источник: AC — «מועמד שאינו יכול להתחיל בגלל חוסר תרחיש מסומן כך ברשימת המועמדים».
    const row = await candidateRow(business, name);
    await expect(row).toContainText('קישור נוצר');
    await expect(row.getByText(MARKER, { exact: true })).toBeVisible();
    await expect(row.locator(`[title="${TOOLTIP}"]`).first()).toBeAttached();

    // Контроль: у кандидатов версии со сценарием метки нет.
    await business.goto('/candidates');
    await expect(business.getByRole('heading', { level: 1, name: 'מועמדים' })).toBeVisible();
    const withScenario = business.getByRole('row').filter({ hasText: SIMULATION }).filter({ hasNotText: NO_SCENARIO_SIMULATION });
    const n = Math.min(await withScenario.count(), 10);
    if (n === 0) test.info().annotations.push({ type: 'note', description: `нет строк «${SIMULATION}» для контроля` });
    for (let i = 0; i < n; i++) await expect(withScenario.nth(i)).not.toContainText(MARKER);
  });

  test('гость: «הסימולציה עדיין לא מוכנה» + «לפנות לצוות הגיוס»; после открытия метка в списке остаётся @desktop @data #d9aa30282ea83831ce4afdeb', async ({ asUser }) => {
    expect(link, 'нет ссылки из предыдущего теста').not.toBe('');
    const guest = await asUser('guest');
    await guest.setViewportSize({ width: 390, height: 844 });

    for (const reload of [false, true]) {
      const open = guest.waitForResponse((r) => r.url().includes('/rpc/candidate_open_link'));
      if (reload) await guest.reload();
      else await guest.goto(link);
      const body = await (await open).json();
      expect(body, 'candidate_open_link').toMatchObject({ stage: 'unavailable', reason: 'no_scenario' });

      await expect(guest.getByText('הסימולציה עדיין לא מוכנה')).toBeVisible();
      await expect(guest.getByText(/התרחיש של השיחה עוד לא הושלם/)).toBeVisible();
      const contact = guest.getByRole('button', { name: 'לפנות לצוות הגיוס' }).or(guest.getByRole('link', { name: 'לפנות לצוות הגיוס' }));
      await expect(contact.first()).toBeVisible();
      await expect(guest.getByRole('button', { name: 'בוא נתחיל' })).toHaveCount(0);
    }

    // Источник: «מצב נדרש» — «העסק רואה ברשימה את הסיבה שבגללה המועמד אינו יכול להתחיל».
    const business = await asUser('business');
    const row = await candidateRow(business, name);
    await expect(row.getByText(MARKER, { exact: true })).toBeVisible();
  });
});
